/* eslint-disable @next/next/no-img-element */

type Props = {
  /** Path without width suffix or extension, e.g. "/images/hero" */
  base: string;
  /** Widths generated by scripts/optimize-images.mjs */
  widths?: number[];
  sizes: string;
  alt?: string;
  priority?: boolean;
  className?: string;
};

export default function ResponsiveImage({
  base,
  widths = [640, 1280, 1920],
  sizes,
  alt = "",
  priority = false,
  className,
}: Props) {
  const srcSet = widths.map((w) => `${base}-${w}.webp ${w}w`).join(", ");
  const fallback = widths[Math.min(1, widths.length - 1)];

  return (
    <img
      className={className}
      src={`${base}-${fallback}.webp`}
      srcSet={srcSet}
      sizes={sizes}
      alt={alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding={priority ? "sync" : "async"}
      draggable={false}
    />
  );
}
